import java.util.*;
import java.io.*;

public class MinCostFlow {
    static class Edge {
        int to, cap, cost, rev;
        public Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static final int maxn = 6000;
    static final int inf = Integer.MAX_VALUE;
    static final long inff = 1000000000000000000L;
    static List<Edge>[] G = new ArrayList[maxn];
    static int[] dist = new int[maxn];
    static int[] prevv = new int[maxn];
    static int[] preve = new int[maxn];
    static int[] inq = new int[maxn];

    static int n, s, t;
    static int[] A = new int[58];
    static List<Integer>[] H = new ArrayList[57];

    static void initialize(int _n, int _s, int _t) {
        for (int i = 0; i <= _n; i++) {
            G[i] = new ArrayList<>();
        }
        n = _n;
        s = _s;
        t = _t;
    }

    static void create_edge(int from, int to, int cap, int cost) {
        G[from].add(new Edge(to, cap, cost, G[to].size()));
        G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
    }

    static long compute_min_cost_flow(int flow_needed) {
        long total_cost = 0;
        while (flow_needed > 0) {
            Arrays.fill(dist, 0, n, (int) inff);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            Arrays.fill(inq, 0, n, 0);
            inq[s] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                inq[u] = 0;
                for (int i = 0; i < G[u].size(); i++) {
                    Edge e = G[u].get(i);
                    if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        prevv[e.to] = u;
                        preve[e.to] = i;
                        if (inq[e.to] == 0) {
                            inq[e.to] = 1;
                            q.offer(e.to);
                        }
                    }
                }
            }
            if (dist[t] == inff) return -1;
            int d = flow_needed;
            for (int v = t; v != s; v = prevv[v]) {
                d = Math.min(d, G[prevv[v]].get(preve[v]).cap);
            }
            flow_needed -= d;
            total_cost += (long) d * dist[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge e = G[prevv[v]].get(preve[v]);
                e.cap -= d;
                G[v].get(e.rev).cap += d;
            }
        }
        return total_cost;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= K; i++) {
            int X = Integer.parseInt(br.readLine());
            A[X]++;
        }

        for (int i = 0; i < 57; i++) {
            H[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int X = Integer.parseInt(st.nextToken());
            int Y = Integer.parseInt(st.nextToken());
            H[X].add(Y);
            H[Y].add(X);
        }

        initialize(5103, 0, 5101);
        for (int i = 2; i <= N; i++) {
            create_edge(0, i, A[i], 0);
        }

        for (int i = 0; i <= 100; i++) {
            for (int l = 1; l <= N; l++) {
                create_edge(50 * i + l, 50 * (i + 1) + l, K, 0);
                for (int j : H[l]) {
                    for (int k = 1; k <= K; k++) {
                        create_edge(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                    }
                }
            }
        }

        for (int i = 1; i <= 101; i++) {
            create_edge(50 * i + 1, 5101, K, C * i);
        }

        System.out.println(compute_min_cost_flow(K));
    }
}
